import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    if not data:
        raise ValueError("Empty JSON data")
    if not isinstance(data, list):
        raise ValueError("JSON data must be a list")
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")
        if "country" not in item or "population" not in item:
            raise ValueError("Each dictionary must contain 'country' and 'population' keys")
        if not isinstance(item["country"], str):
            raise ValueError("Country must be a string")
        pop = item["population"]
        if not isinstance(pop, (int, float)):
            raise ValueError("Population must be numeric")
        if pop < 0:
            raise ValueError("Population cannot be negative")
    records = []
    for item in data:
        country = item["country"]
        population = item["population"]
        if isinstance(population, float):
            population = math.floor(population)
        records.append({"Country": country, "Population": population})
    df = pd.DataFrame(records)
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except OSError:
        raise IOError("Cannot write file to specified directory")
    return file_path, df
